arguments.command:
python -m py_compile report.py && python -c 'from report import report_time; assert report_time("2024-01-02T03:04:05+08:00") == "2024-01-02 03:04:05 +0800"; assert report_time("2024-01-02T03:04:05Z") == "2024-01-02 03:04:05 +0000"; assert report_time("2024-01-02T03:04:05.987654-05:30") == "2024-01-02 03:04:05 -0530"; 
try: report_time("2024-01-02T03:04:05")
except ValueError: pass
else: raise AssertionError("naive timestamp accepted")
try: report_time(123)
except TypeError: pass
else: raise AssertionError("non-string accepted")'
